 --brand:var(--canon-brand,#7CC4FF);--brand-dark:var(--canon-brand-dark,#E7F0FA);--brand-light:var(--canon-brand-light,#7CC4FF);--sand:var(--canon-sand,#D2B48C);--mist:var(--canon-mist,#091420);
 --surface:var(--canon-surface,#112131);--ink:var(--canon-ink,#E7F0FA);--blue:var(--canon-blue,#7CC4FF);--page:var(--canon-page,#091420);--canvas:var(--canon-canvas,#16283A);
 --text:var(--canon-text,#C8D7E6);--muted:var(--canon-muted,#A5B8CB);--line:var(--canon-line,#30465A);--faint-line:var(--canon-faint-line,#253B4F);
 --blue-soft:var(--canon-blue-soft,#1B3852);--sand-soft:var(--canon-sand-soft,#332E2A);--neutral:var(--canon-neutral,#1B3043);
 --success:var(--canon-success,#3EAA83);--success-text:var(--canon-success-text,#76D9B2);--success-soft:var(--canon-success-soft,#163D36);
 --caution:var(--canon-caution,#BB9349);--caution-text:var(--canon-caution-text,#EAC278);--caution-soft:var(--canon-caution-soft,#3C3425);
 --negative:var(--canon-negative,#C66A64);--negative-text:var(--canon-negative-text,#FF9B94);--negative-soft:var(--canon-negative-soft,#442C34);
 --unknown:var(--canon-unknown,#96ABBF);--unknown-soft:var(--canon-unknown-soft,#1C2F40);--reference:var(--canon-reference,#A8BED3);
}
html[data-srm-theme] body {background:var(--page);color:var(--ink)}
.canon-studio-bar{gap:20px}
.srm-theme-spec{border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:24px;margin-bottom:24px}
.srm-theme-spec-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:22px}
.srm-theme-spec-heading h2{font-size:22px;font-weight:550;letter-spacing:-.6px;margin:7px 0}
.srm-theme-spec p{font-size:12px;line-height:1.75;color:var(--muted)}
.srm-theme-preview{display:grid;grid-template-columns:1.2fr 1fr;align-items:center;gap:24px;padding:26px 30px;border-radius:10px;background:var(--page);border:1px solid var(--faint-line);margin-bottom:22px}
.srm-theme-preview h3{font-size:24px;font-weight:500;letter-spacing:-.7px;margin:10px 0}
.srm-theme-preview p{max-width:340px}.srm-theme-preview-actions{display:flex;align-items:center;gap:20px;flex-wrap:wrap;margin-top:20px}
.srm-theme-positive{color:var(--success-text);font-size:14px;font-weight:600}.srm-theme-positive small{display:block;font-size:10px;font-weight:400;margin-top:3px}
.srm-theme-mini-chart{min-width:0}.srm-theme-mini-chart>div{display:flex;align-items:baseline;justify-content:space-between;gap:10px;color:var(--muted);font-size:11px;margin-bottom:14px}.srm-theme-mini-chart strong{font-weight:500;font-size:24px;color:var(--ink);white-space:nowrap}.srm-theme-mini-chart small{font-size:11px;font-weight:400;color:var(--muted)}.srm-theme-mini-chart svg{width:100%;display:block;overflow:visible}
.srm-theme-palette{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px 14px}.srm-theme-palette>div{display:flex;align-items:center;gap:10px}.srm-theme-swatch{height:30px;width:30px;flex:none;border:1px solid var(--line);border-radius:8px}.srm-theme-palette strong{display:block;font-size:11px;font-weight:500}.srm-theme-palette small{display:block;font-size:10px;color:var(--muted);margin-top:3px;font-variant-numeric:tabular-nums}.srm-theme-spec .srm-theme-rule{border-top:1px solid var(--faint-line);margin-top:22px;padding-top:16px;font-size:11px}
/* Fixed brand assets retain their approved colors on a deliberate light stage. */
[data-srm-theme="dark"] :is(.lib-logo-stage,.lib-logo-preview,.srm-company-logo){background:#fff;border-radius:7px;padding:6px}
[data-srm-theme="dark"] .srm-history-year-pill{color:var(--chart-year-ink)}
[data-srm-theme="dark"] ::selection{background:#315D80;color:#fff}
[data-srm-theme="dark"] ::placeholder{color:#8FA5BA;opacity:1}
[data-srm-theme="dark"] :is(input,textarea,select){color-scheme:dark}
@media(max-width:1060px){.canon-state{display:none}}
@media(max-width:760px){.canon-studio-bar{gap:7px}.srm-theme-preview{grid-template-columns:1fr;padding:20px}.srm-theme-palette{grid-template-columns:repeat(2,minmax(0,1fr))}.srm-theme-spec{padding:20px}.srm-theme-spec-heading{flex-wrap:wrap}}
@media(prefers-reduced-motion:reduce){}
.v3-header nav{flex-wrap:wrap;justify-content:flex-end;max-width:400px}
[data-srm-theme=dark] .v3-app{--cci-series-copper:var(--brand);--cci-series-pvc:var(--theme-reference);--cci-series-energy:var(--sand);--cci-series-labor:var(--theme-muted);--cci-series-transport:var(--theme-positive)}
[data-srm-theme=dark] .v3-app .v3-primary{background:var(--action-fill);color:#fff;border-color:var(--action-fill)}
[data-srm-theme=dark] .v3-app .v3-primary:hover{background:var(--chrome-strong);color:#fff}

@media(max-width:760px){.v3-header{flex-wrap:wrap}.v3-header nav{max-width:none;flex-wrap:wrap}}

/* FND-05 / SRM-C95: one icon-only action representing the NEXT mode (moon -> dark, sun -> light).
   The 2.75rem target matches SRM-SP05; no segmented pill, visible text, or extra outer border. */
.srm-theme-switch{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;width:2.75rem;height:2.75rem;min-width:2.75rem;margin:0;padding:0;border:0;background:transparent;color:var(--ink);font:12px/1.2 Inter,Arial,sans-serif}
.srm-theme-switch button,.canon-studio-bar .srm-theme-switch button{box-sizing:border-box;display:inline-flex;align-items:center;justify-content:center;flex:none;width:2.75rem;height:2.75rem;min-width:2.75rem;min-height:2.75rem;margin:0;padding:0;border:1px solid var(--line);border-radius:var(--canon-actionRadius,7px);background:var(--surface);color:var(--ink);font:inherit;cursor:pointer;transition:background-color 180ms,border-color 180ms,color 180ms;transform:none;scale:1}
.srm-theme-switch button svg{display:block;width:1.125rem;height:1.125rem;flex:none}
.srm-theme-switch button:hover,.canon-studio-bar .srm-theme-switch button:hover{color:var(--brand);background:var(--blue-soft);border-color:var(--brand-light)}
.srm-theme-switch button:focus-visible{outline:2px solid var(--brand-light);outline-offset:3px}
.canon-studio-bar>.srm-theme-switch{margin-left:0}
@media(prefers-reduced-motion:reduce){.srm-theme-switch button{transition:none!important}}
